input.content:
/**
 * The Restaurant Arena floor plan, as pure geometry.
 *
 * Everything the scene draws is authored against one baseline canvas
 * (`ARENA_BASELINE`, 520×740 CSS pixels). This module turns a real canvas
 * size into the rects that floor plan occupies there, plus the three
 * decisions that change *how* the scene draws rather than only where:
 *
 * - `scale` — 1 at the baseline, larger on a bigger window, so text and the
 *   spacing around it grow with the room instead of staying at the size a
 *   520px-wide canvas needed. Capped, because past `ARENA_MAX_SCALE` a
 *   bigger window is better spent on a bigger floor than on bigger type.
 * - `compact` — a canvas too small for the full plan. Nothing grows here
 *   (`scale` stays 1); the bands tighten instead.
 * - `feedBeside` — on a wide window the service log is a tall rail beside
 *   the floor; on a narrow one it stacks underneath.
 *
 * Every rect returned is inside `width`×`height`: the caller can draw into
 * any of them without clipping, at any size, without checking first.
 */

export type ArenaRect = { x: number; y: number; width: number; height: number };
export type ArenaPoint = { x: number; y: number };
export type ArenaLocation = "floor" | "kitchen" | "pass" | "queue";

export interface RestaurantArenaLayout {
  compact: boolean;
  scale: number;
  feedBeside: boolean;
  topBar: ArenaRect;
  brief: ArenaRect;
  kitchen: ArenaRect;
  pass: ArenaRect;
  dining: ArenaRect;
  door: ArenaRect;
  doorStand: ArenaRect;
  waypoints: Record<ArenaLocation, ArenaPoint>;
  /** Y coordinate of the hallway line that runs through the pass zone. */
  spineY: number;
  tickets: ArenaRect;
  feed: ArenaRect;
}

/** The canvas this floor plan is authored against: `scale` is exactly 1 here. */
export const ARENA_BASELINE = { width: 520, height: 740 } as const;

/** Narrower than this and the plan tightens instead of growing. */
export const ARENA_COMPACT_WIDTH = 460;
/** Shorter than this and the plan tightens instead of growing. */
export const ARENA_COMPACT_HEIGHT = 420;

/** Wide enough to seat the service log beside the floor rather than under it. */
export const ARENA_FEED_BESIDE_WIDTH = 600;

/**
 * Ceiling on `scale`. A 4K window does not want 40px body copy — past
 * roughly twice the baseline the extra room should go to the floor.
 */
export const ARENA_MAX_SCALE = 1.9;

/** The host stand has to stay a readable target however small the canvas is. */
export const ARENA_DOOR_STAND_MIN = { width: 56, height: 22 } as const;

function clamp(value: number, min: number, max: number): number {
  return Math.min(Math.max(value, min), max);
}

/**
 * Keep a rect inside the canvas: slide it in first, and only shrink it if it
 * genuinely does not fit. Sliding rather than shrinking is what lets
 * `doorStand` hold its minimum size (see `ARENA_DOOR_STAND_MIN`) on a canvas
 * whose door zone is narrower than that minimum.
 */
function fitRect(rect: ArenaRect, w: number, h: number): ArenaRect {
  const width = Math.min(rect.width, w);
  const height = Math.min(rect.height, h);
  return {
    x: clamp(rect.x, 0, w - width),
    y: clamp(rect.y, 0, h - height),
    width,
    height,
  };
}

function center(rect: ArenaRect): ArenaPoint {
  return { x: rect.x + rect.width / 2, y: rect.y + rect.height / 2 };
}

/**
 * How much bigger than the baseline this canvas is, in the dimension that
 * has the *least* room to spare — growing on width alone would push the
 * bottom band off a short window.
 */
export function arenaScale(width: number, height: number): number {
  if (width < ARENA_COMPACT_WIDTH || height < ARENA_COMPACT_HEIGHT) return 1;
  const growth = Math.min(width / ARENA_BASELINE.width, height / ARENA_BASELINE.height);
  return clamp(growth, 1, ARENA_MAX_SCALE);
}

export function restaurantArenaLayout(width: number, height: number): RestaurantArenaLayout {
  const w = Math.max(1, Math.round(Number.isFinite(width) ? width : ARENA_BASELINE.width));
  const h = Math.max(1, Math.round(Number.isFinite(height) ? height : ARENA_BASELINE.height));

  const compact = w < ARENA_COMPACT_WIDTH || h < ARENA_COMPACT_HEIGHT;
  const scale = arenaScale(w, h);
  const feedBeside = w >= ARENA_FEED_BESIDE_WIDTH;

  /** A length designed at the baseline, in this canvas' units. */
  const u = (px: number) => Math.max(1, Math.round(px * scale));

  const margin = clamp(compact ? 5 : u(8), 1, Math.floor(Math.min(w, h) * 0.04));
  const gap = clamp(compact ? 4 : u(6), 1, Math.floor(Math.min(w, h) * 0.03));
  const contentW = Math.max(1, w - margin * 2);
  const contentH = Math.max(1, h - margin * 2);

  // ── Horizontal split: floor column, and the feed rail beside it ──────
  const feedW = feedBeside
    ? clamp(u(compact ? 150 : 190), Math.round(contentW * 0.2), Math.round(contentW * 0.34))
    : 0;
  const bodyX = margin;
  const bodyW = Math.max(1, contentW - (feedBeside ? feedW + gap : 0));

  // ── Vertical bands. Each one is capped as a fraction of the content box,
  // so a short window squeezes the chrome and still leaves a floor. ──────
  const band = (px: number, fraction: number) =>
    Math.max(1, Math.min(u(px), Math.floor(contentH * fraction)));
  const topBarH = band(compact ? 30 : 38, 0.1);
  const briefH = band(compact ? 26 : 32, 0.09);
  const ticketsH = band(compact ? 54 : 72, 0.16);
  const feedH = feedBeside
    ? 0
    : Math.max(1, Math.min(Math.max(u(compact ? 72 : 104), Math.round(h * 0.18)), Math.floor(contentH * 0.26)));
  const rowGaps = gap * (feedBeside ? 3 : 4);
  const floorH = Math.max(1, contentH - topBarH - briefH - ticketsH - feedH - rowGaps);

  const briefY = margin + topBarH + gap;
  const bodyY = briefY + briefH + gap;
  const ticketsY = bodyY + floorH + gap;

  // ── The floor itself: kitchen | pass | dining over the door ──────────
  const kitchenW = Math.max(1, Math.round(bodyW * 0.26));
  const passW = Math.max(1, Math.min(u(26), Math.round(bodyW * 0.09)));
  const diningX = bodyX + kitchenW + gap + passW + gap;
  const diningW = Math.max(1, bodyX + bodyW - diningX);
  const doorH = clamp(
    Math.max(u(compact ? 44 : 58), Math.round(floorH * 0.3)),
    1,
    Math.max(1, floorH - gap - 1),
  );
  const diningH = Math.max(1, floorH - doorH - gap);

  const kitchen = fitRect({ x: bodyX, y: bodyY, width: kitchenW, height: floorH }, w, h);
  const pass = fitRect({ x: bodyX + kitchenW + gap, y: bodyY, width: passW, height: floorH }, w, h);
  const dining = fitRect({ x: diningX, y: bodyY, width: diningW, height: diningH }, w, h);
  const door = fitRect({ x: diningX, y: bodyY + diningH + gap, width: diningW, height: doorH }, w, h);

  // The host stand: a real desk inside the door zone, never smaller than a
  // fingertip even when the door zone itself is tiny.
  const labelH = compact ? 11 : u(14);
  const standW = Math.max(
    ARENA_DOOR_STAND_MIN.width,
    Math.min(u(90), Math.round(door.width * 0.36)),
  );
  const standH = Math.max(
    ARENA_DOOR_STAND_MIN.height,
    Math.min(u(36), door.height - labelH - u(4)),
  );
  const hostGutter = Math.min(u(40), Math.max(0, door.width - standW - gap));
  const doorStand = fitRect(
    { x: door.x + hostGutter, y: door.y + labelH, width: standW, height: standH },
    w,
    h,
  );

  // ── The hallway. Staff walk this line between rooms instead of cutting
  // diagonally across them, so it has to cross the pass (the only way
  // through from the kitchen) and stay inside the dining room it also
  // crosses on the way to the door. ──────────────────────────────────────
  const spineY = clamp(pass.y + pass.height / 2, dining.y, dining.y + dining.height);

  const waypoints: Record<ArenaLocation, ArenaPoint> = {
    kitchen: { x: kitchen.x + kitchen.width / 2, y: clamp(spineY, kitchen.y, kitchen.y + kitchen.height) },
    pass: { x: pass.x + pass.width / 2, y: spineY },
    floor: center(dining),
    queue: center(doorStand),
  };

  return {
    compact,
    scale,
    feedBeside,
    topBar: fitRect({ x: margin, y: margin, width: contentW, height: topBarH }, w, h),
    brief: fitRect({ x: margin, y: briefY, width: contentW, height: briefH }, w, h),
    kitchen,
    pass,
    dining,
    door,
    doorStand,
    waypoints,
    spineY,
    tickets: fitRect({ x: bodyX, y: ticketsY, width: bodyW, height: ticketsH }, w, h),
    feed: fitRect(
      feedBeside
        ? {
            x: bodyX + bodyW + gap,
            y: bodyY,
            width: feedW,
            height: Math.max(1, ticketsY + ticketsH - bodyY),
          }
        : { x: margin, y: ticketsY + ticketsH + gap, width: contentW, height: feedH },
      w,
      h,
    ),
  };
}

