input.content:
/**
 * Staff movement across the Restaurant Arena floor.
 *
 * The floor is not an open field: the four staff locations sit on one
 * hallway — kitchen ↔ pass ↔ floor ↔ queue — and the pass and the dining
 * floor are through-stations, not shortcuts. A chef sent to the door walks
 * out through the pass and across the dining room like a person would,
 * which is also exactly what the kitchen→queue path says (`bfsPath`).
 *
 * `corridorPoints` turns such a path into pixels that ride the hallway line
 * (`spineY` from the layout) rather than cutting a diagonal through the
 * middle of a room, and `StaffWalker` walks it one eased hop at a time.
 */

import type { ArenaLocation, ArenaPoint } from "./restaurant-arena-layout.js";

export type WalkNode = ArenaLocation;
export type Point = ArenaPoint;

/**
 * The floor as a graph. One hallway, no diagonals: every edge is a doorway
 * a person could actually walk through, so `kitchen`↔`queue` has to be
 * travelled via `pass` and `floor`.
 */
export const WALK_GRAPH: Record<WalkNode, readonly WalkNode[]> = {
  kitchen: ["pass"],
  pass: ["kitchen", "floor"],
  floor: ["pass", "queue"],
  queue: ["floor"],
};

/** Staff walk at a brisk-but-not-running pace, in pixels per second. */
export const WALK_SPEED_PX_PER_SEC = 200;

/** Two points within this many pixels of each other count as the same spot. */
const EPSILON = 0.5;

/**
 * Shortest node path from `from` to `to`, inclusive of both ends, so
 * `bfsPath("kitchen", "queue")` is the full itinerary
 * `["kitchen", "pass", "floor", "queue"]` and `bfsPath(n, n)` is `[n]`.
 * Empty only if `to` is unreachable, which the graph above never is.
 */
export function bfsPath(from: WalkNode, to: WalkNode): WalkNode[] {
  if (from === to) return [from];
  const previous = new Map<WalkNode, WalkNode>();
  const seen = new Set<WalkNode>([from]);
  const queue: WalkNode[] = [from];

  while (queue.length > 0) {
    const node = queue.shift()!;
    for (const next of WALK_GRAPH[node] ?? []) {
      if (seen.has(next)) continue;
      seen.add(next);
      previous.set(next, node);
      if (next === to) {
        const path: WalkNode[] = [to];
        let step: WalkNode | undefined = to;
        while ((step = previous.get(step!)) !== undefined) path.unshift(step);
        return path;
      }
      queue.push(next);
    }
  }
  return [];
}

