  y: number;
  facing: 1 | -1 = 1;
  walking = false;
  dragging = false;
  node: WalkNode;

  /** Remaining hops, in order; `hops[0]` is the one in progress. */
  private hops: Point[] = [];
  private from: Point;
  private elapsedMs = 0;
  private durationMs = 0;

  constructor(node: WalkNode, slot: Point) {
    this.node = node;
    this.x = slot.x;
    this.y = slot.y;
    this.from = { x: slot.x, y: slot.y };
  }

