  snap(slot: Point, node: WalkNode): void {
    this.node = node;
    this.x = slot.x;
    this.y = slot.y;
    this.from = { x: slot.x, y: slot.y };
    this.hops = [];
    this.walking = false;
    this.elapsedMs = 0;
    this.durationMs = 0;
  }

