    this.hops = hops;
    this.from = here;
    this.elapsedMs = 0;
    this.durationMs = hops.length > 0 ? hopDurationMs(here, hops[0]!) : 0;
    this.walking = hops.length > 0;
    this.faceToward(hops[0]);
