    return this.x !== startX || this.y !== startY;
  }

  /** Land on the current hop and line up the next one. */
  private arrive(to: Point): void {
    this.x = to.x;
    this.y = to.y;
    this.from = { x: to.x, y: to.y };
    this.hops.shift();
    this.elapsedMs = 0;
    const next = this.hops[0];
    this.durationMs = next ? hopDurationMs(this.from, next) : 0;
    this.faceToward(next);
  }

  /** Turn to face the way we are going, keeping the last facing if we are not. */
  private faceToward(to: Point | undefined): void {
    if (!to) return;
    const dx = to.x - this.x;
    if (Math.abs(dx) < EPSILON) return;
    this.facing = dx > 0 ? 1 : -1;
  }
}

