/**
 * Holds repaints back while the player is dragging.
 *
 * The arena scene repaints from scratch on every state change: it destroys
 * every game object and builds new ones. That is fine at rest and fatal
 * mid-drag — the token under the pointer is destroyed and rebuilt at its old
 * slot, so the drag is yanked out of the player's hand and the drop never
 * lands. So a drag closes the gate: paints asked for while it is open are
 * held, and *one* repaint is owed once the drag ends, however many were
 * asked for (they would all have painted the same latest state anyway).
 *
 * A resize is the exception. The scene it belonged to is torn down and a
 * fresh one is painted at the new size, so there is no drag left to protect
 * and nothing sensible to replay: `resize()` drops both. That is what keeps
 * the `dragend` that arrives after a resize from replaying a paint of a
 * layout nobody is looking at any more.
 */
export class RepaintGate {
  private dragging = false;
  private owed = false;

  /** True while a drag is open — between `beginDrag()` and `endDrag()`/`resize()`. */
  get isDragging(): boolean {
    return this.dragging;
  }

  beginDrag(): void {
    this.dragging = true;
  }

  /**
   * Paints immediately (returns true) unless a drag is open, in which case
   * the paint is held back (returns false) and one repaint becomes owed.
   */
  requestPaint(): boolean {
    if (this.dragging) {
      this.owed = true;
      return false;
    }
    return true;
  }

  /**
   * Ends the drag. Returns whether a repaint was held back during it — and
   * so has to be replayed by the caller now.
   */
  endDrag(): boolean {
    const owed = this.owed;
    this.dragging = false;
    this.owed = false;
    return owed;
  }

  /**
   * Drops any open drag and clears anything owed, since the resize itself
   * repaints from scratch.
   */
  resize(): void {
    this.dragging = false;
    this.owed = false;
  }
}

