import { describe, expect, it } from "bun:test";
import {
  ARENA_BASELINE,
  ARENA_DOOR_STAND_MIN,
  ARENA_MAX_SCALE,
  restaurantArenaLayout,
  type ArenaRect,
  type RestaurantArenaLayout,
} from "./restaurant-arena-layout.js";

const RECT_KEYS = ["topBar", "brief", "kitchen", "pass", "dining", "door", "doorStand", "tickets", "feed"] as const;

const SIZES: [number, number][] = [
  [320, 240],
  [380, 300],
  [460, 420],
  [520, 740],
  [600, 400],
  [760, 620],
  [1024, 768],
  [1440, 900],
  [1920, 1200],
  [2560, 1600],
  [3840, 2160],
];

function rects(layout: RestaurantArenaLayout): [string, ArenaRect][] {
  return RECT_KEYS.map((key) => [key, layout[key]]);
}

describe("restaurantArenaLayout", () => {
  it("is the baseline canvas at scale 1", () => {
    const layout = restaurantArenaLayout(ARENA_BASELINE.width, ARENA_BASELINE.height);
    expect(layout.scale).toBe(1);
    expect(layout.compact).toBe(false);
    expect(layout.feedBeside).toBe(false);
  });

  it("grows with whichever dimension has the least room to spare", () => {
    // Twice as wide but the same height: height is the constraint, so the
    // type does not grow for the extra width alone.
    expect(restaurantArenaLayout(1040, 740).scale).toBe(1);
    expect(restaurantArenaLayout(780, 1110).scale).toBeCloseTo(1.5, 5);
    expect(restaurantArenaLayout(1040, 1480).scale).toBe(ARENA_MAX_SCALE);
  });

  it("never shrinks below the baseline and never grows past the cap", () => {
    for (const [w, h] of SIZES) {
      const { scale } = restaurantArenaLayout(w, h);
      expect(scale).toBeGreaterThanOrEqual(1);
      expect(scale).toBeLessThanOrEqual(ARENA_MAX_SCALE);
    }
    expect(restaurantArenaLayout(10000, 10000).scale).toBe(ARENA_MAX_SCALE);
  });

  it("stays compact and skips growing text on a small canvas", () => {
    for (const [w, h] of [
      [440, 900],
      [900, 400],
      [320, 240],
    ] as [number, number][]) {
      const layout = restaurantArenaLayout(w, h);
      expect(layout.compact).toBe(true);
      expect(layout.scale).toBe(1);
    }
    expect(restaurantArenaLayout(460, 420).compact).toBe(false);
  });

  it("seats the feed beside the floor only once the window is wide enough", () => {
    expect(restaurantArenaLayout(520, 740).feedBeside).toBe(false);
    expect(restaurantArenaLayout(599, 900).feedBeside).toBe(false);
    expect(restaurantArenaLayout(600, 900).feedBeside).toBe(true);

    const beside = restaurantArenaLayout(1280, 800);
    expect(beside.feed.x).toBeGreaterThan(beside.dining.x + beside.dining.width - 1);
    expect(beside.feed.y).toBeLessThan(beside.tickets.y);

    const below = restaurantArenaLayout(520, 740);
    expect(below.feed.y).toBeGreaterThanOrEqual(below.tickets.y + below.tickets.height);
  });

  it("fits every rect inside the canvas at every size", () => {
    for (const [w, h] of SIZES) {
      const layout = restaurantArenaLayout(w, h);
      for (const [name, rect] of rects(layout)) {
        expect(rect.width, `${name} width at ${w}x${h}`).toBeGreaterThan(0);
        expect(rect.height, `${name} height at ${w}x${h}`).toBeGreaterThan(0);
        expect(rect.x, `${name} x at ${w}x${h}`).toBeGreaterThanOrEqual(0);
        expect(rect.y, `${name} y at ${w}x${h}`).toBeGreaterThanOrEqual(0);
        expect(rect.x + rect.width, `${name} right at ${w}x${h}`).toBeLessThanOrEqual(w);
        expect(rect.y + rect.height, `${name} bottom at ${w}x${h}`).toBeLessThanOrEqual(h);
      }
    }
  });

  it("keeps the floor zones side by side without overlapping", () => {
    for (const [w, h] of SIZES) {
      const { kitchen, pass, dining, door } = restaurantArenaLayout(w, h);
      expect(kitchen.x + kitchen.width, `${w}x${h}`).toBeLessThanOrEqual(pass.x);
      expect(pass.x + pass.width, `${w}x${h}`).toBeLessThanOrEqual(dining.x);
      expect(dining.y + dining.height, `${w}x${h}`).toBeLessThanOrEqual(door.y);
      expect(door.x).toBe(dining.x);
    }
  });

  it("keeps the host stand a usable target at any size", () => {
    for (const [w, h] of SIZES) {
      const { doorStand } = restaurantArenaLayout(w, h);
      expect(doorStand.width, `${w}x${h}`).toBeGreaterThanOrEqual(ARENA_DOOR_STAND_MIN.width);
      expect(doorStand.height, `${w}x${h}`).toBeGreaterThanOrEqual(ARENA_DOOR_STAND_MIN.height);
    }
  });

  it("runs the hallway through the pass, and parks staff on it", () => {
    for (const [w, h] of SIZES) {
      const layout = restaurantArenaLayout(w, h);
      expect(layout.spineY, `${w}x${h}`).toBeGreaterThanOrEqual(layout.pass.y);
      expect(layout.spineY, `${w}x${h}`).toBeLessThanOrEqual(layout.pass.y + layout.pass.height);
      // The hallway also has to cross the dining room it runs through.
