      expect(inside(layout.waypoints.pass, layout.pass), `pass at ${w}x${h}`).toBe(true);
      expect(inside(layout.waypoints.floor, layout.dining), `floor at ${w}x${h}`).toBe(true);
      expect(inside(layout.waypoints.queue, layout.doorStand), `queue at ${w}x${h}`).toBe(true);
    }
  });

  it("survives a degenerate canvas instead of returning nonsense", () => {
    for (const [w, h] of [
      [0, 0],
      [1, 1],
      [80, 60],
      [Number.NaN, Number.NaN],
    ] as [number, number][]) {
