import { describe, expect, it } from "bun:test";
import { restaurantArenaLayout } from "./restaurant-arena-layout.js";
import {
  bfsPath,
  corridorPoints,
  hopDurationMs,
  StaffWalker,
  WALK_GRAPH,
  WALK_SPEED_PX_PER_SEC,
  type Point,
  type WalkNode,
} from "./staff-walk.js";

const layout = restaurantArenaLayout(1024, 768);
const waypoints = layout.waypoints;
const spineY = layout.spineY;

/** Run a walk to completion, collecting every position it passed through. */
function walkOut(walker: StaffWalker, stepMs = 16, limit = 4000): Point[] {
  const track: Point[] = [{ x: walker.x, y: walker.y }];
  for (let i = 0; i < limit && walker.walking; i++) {
    if (walker.step(stepMs, 1)) track.push({ x: walker.x, y: walker.y });
  }
  return track;
}

describe("WALK_GRAPH / bfsPath", () => {
  it("wires the four locations as one hallway", () => {
    expect(Object.keys(WALK_GRAPH).sort()).toEqual(["floor", "kitchen", "pass", "queue"]);
    for (const [node, neighbours] of Object.entries(WALK_GRAPH) as [WalkNode, readonly WalkNode[]][]) {
      for (const neighbour of neighbours) {
        expect(WALK_GRAPH[neighbour], `${neighbour} should link back to ${node}`).toContain(node);
      }
    }
    // The ends of the hallway are ends: no kitchen door onto the street.
    expect(WALK_GRAPH.kitchen).not.toContain("queue");
    expect(WALK_GRAPH.queue).not.toContain("kitchen");
  });

  it("routes kitchen to queue through both through-stations", () => {
    expect(bfsPath("kitchen", "queue")).toEqual(["kitchen", "pass", "floor", "queue"]);
    expect(bfsPath("queue", "kitchen")).toEqual(["queue", "floor", "pass", "kitchen"]);
  });

  it("routes the short trips too", () => {
    expect(bfsPath("kitchen", "pass")).toEqual(["kitchen", "pass"]);
    expect(bfsPath("kitchen", "floor")).toEqual(["kitchen", "pass", "floor"]);
    expect(bfsPath("floor", "queue")).toEqual(["floor", "queue"]);
    expect(bfsPath("pass", "pass")).toEqual(["pass"]);
  });
});

describe("corridorPoints", () => {
  it("rides the hallway instead of cutting across the rooms", () => {
    const points = corridorPoints(waypoints.kitchen, ["pass", "floor", "queue"], waypoints, spineY);
    expect(points.length).toBeGreaterThan(0);
    expect(points.some((point) => point.y === spineY)).toBe(true);

    // Every segment, the first one included, is axis-aligned: no diagonals
    // through the middle of the dining room.
    let previous: Point = waypoints.kitchen;
    for (const point of points) {
      const straight = Math.abs(point.x - previous.x) < 0.5 || Math.abs(point.y - previous.y) < 0.5;
      expect(straight, `${JSON.stringify(previous)} -> ${JSON.stringify(point)}`).toBe(true);
      previous = point;
    }
    expect(previous).toEqual(waypoints.queue);
  });

  it("does not repeat the point it starts on, and stops for nowhere to go", () => {
    expect(corridorPoints(waypoints.pass, [], waypoints, spineY)).toEqual([]);
    const points = corridorPoints(waypoints.kitchen, ["pass"], waypoints, spineY);
    expect(points).not.toContainEqual(waypoints.kitchen);
    expect(points[points.length - 1]).toEqual(waypoints.pass);
  });

  it("steps out to the hallway before walking along it", () => {
    const start = { x: waypoints.floor.x, y: waypoints.floor.y };
    const points = corridorPoints(start, ["kitchen"], waypoints, spineY);
    expect(points[0]).toEqual({ x: start.x, y: spineY });
    expect(points[points.length - 1]).toEqual(waypoints.kitchen);
  });
});

describe("hopDurationMs", () => {
  it("walks at the posted speed", () => {
    expect(hopDurationMs({ x: 0, y: 0 }, { x: WALK_SPEED_PX_PER_SEC, y: 0 })).toBeCloseTo(1000, 5);
    expect(hopDurationMs({ x: 0, y: 0 }, { x: 0, y: 100 })).toBeCloseTo(500, 5);
    expect(hopDurationMs({ x: 12, y: 9 }, { x: 12, y: 9 })).toBe(0);
  });
});

describe("StaffWalker", () => {
  it("starts parked on its slot", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    expect(walker.x).toBe(waypoints.kitchen.x);
    expect(walker.y).toBe(waypoints.kitchen.y);
    expect(walker.walking).toBe(false);
    expect(walker.dragging).toBe(false);
    expect(walker.node).toBe("kitchen");
    expect(walker.step(16, 1)).toBe(false);
  });

  it("walks the hallway from the kitchen to the door and arrives on the slot", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("queue", waypoints, spineY);
    expect(walker.node).toBe("queue");
    expect(walker.walking).toBe(true);

    const track = walkOut(walker);
    expect(walker.walking).toBe(false);
    expect(walker.x).toBeCloseTo(waypoints.queue.x, 5);
    expect(walker.y).toBeCloseTo(waypoints.queue.y, 5);
    // It went through the dining room on the way, not around it.
    expect(track.some((point) => Math.abs(point.y - spineY) < 1)).toBe(true);
    expect(track.length).toBeGreaterThan(4);
  });

  it("faces the way it is walking", () => {
    const out = new StaffWalker("kitchen", waypoints.kitchen);
    out.setTarget("queue", waypoints, spineY);
    out.step(16, 1);
    expect(out.facing).toBe(1);

    const back = new StaffWalker("queue", waypoints.queue);
    back.setTarget("kitchen", waypoints, spineY);
    walkOut(back, 16, 200);
    expect(back.facing).toBe(-1);
  });

  it("takes about as long as the distance says it should", () => {
    const walker = new StaffWalker("floor", waypoints.floor);
    walker.setTarget("queue", waypoints, spineY);
    let elapsed = 0;
    while (walker.walking && elapsed < 20000) {
      walker.step(10, 1);
      elapsed += 10;
    }
    const straight = corridorPoints(waypoints.floor, ["queue"], waypoints, spineY);
    let expected = 0;
    let previous: Point = waypoints.floor;
    for (const point of straight) {
      expected += hopDurationMs(previous, point);
      previous = point;
    }
    expect(elapsed).toBeGreaterThanOrEqual(expected);
    expect(elapsed).toBeLessThan(expected + 60);
  });

  it("is paused by speed 0 and doubled by speed 2", () => {
    const paused = new StaffWalker("kitchen", waypoints.kitchen);
    paused.setTarget("pass", waypoints, spineY);
    expect(paused.step(100, 0)).toBe(false);
    expect(paused.x).toBe(waypoints.kitchen.x);

    const slow = new StaffWalker("kitchen", waypoints.kitchen);
    slow.setTarget("pass", waypoints, spineY);
    const fast = new StaffWalker("kitchen", waypoints.kitchen);
    fast.setTarget("pass", waypoints, spineY);
    slow.step(100, 1);
    fast.step(50, 2);
    expect(fast.x).toBeCloseTo(slow.x, 5);
  });

  it("holds still while the player is dragging it", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("queue", waypoints, spineY);
    walker.dragging = true;
    walker.x = 12;
    walker.y = 34;
    expect(walker.step(500, 1)).toBe(false);
    expect(walker.x).toBe(12);
    expect(walker.y).toBe(34);
  });

  it("snaps onto a dropped slot with no walk left in flight", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("queue", waypoints, spineY);
    walker.step(80, 1);
    walker.snap({ x: 200, y: 300 }, "pass");
    expect(walker.node).toBe("pass");
    expect(walker.walking).toBe(false);
    expect(walker.x).toBe(200);
    expect(walker.y).toBe(300);
    expect(walker.step(500, 1)).toBe(false);
  });

  it("shuffles to a moved slot inside the room it is already in", () => {
    const walker = new StaffWalker("floor", waypoints.floor);
    const moved = { ...waypoints, floor: { x: waypoints.floor.x + 24, y: waypoints.floor.y } };
    walker.setTarget("floor", moved, spineY);
    expect(walker.walking).toBe(true);
    walkOut(walker);
    expect(walker.x).toBeCloseTo(moved.floor.x, 5);
    expect(walker.y).toBeCloseTo(moved.floor.y, 5);
    // A shuffle across the room does not detour down to the hallway.
    expect(walker.y).not.toBeCloseTo(spineY, 5);
  });

  it("re-targeting the slot it is already parked on is a no-op", () => {
    const walker = new StaffWalker("pass", waypoints.pass);
    walker.setTarget("pass", waypoints, spineY);
    expect(walker.walking).toBe(false);
    expect(walker.step(200, 1)).toBe(false);
  });

  it("walks to a stacked slot rather than the middle of the zone", () => {
    const slot = { x: waypoints.kitchen.x + 22, y: waypoints.kitchen.y + 4 };
    const walker = new StaffWalker("queue", waypoints.queue);
    walker.setTarget("kitchen", { ...waypoints, kitchen: slot }, spineY);
    walkOut(walker);
    expect(walker.x).toBeCloseTo(slot.x, 5);
    expect(walker.y).toBeCloseTo(slot.y, 5);
  });
});

