private fs(px: number): string {
  // Rounded up, and never below 6px: legibility is the point of scaling,
  // so the smallest labels must not round *down* into illegibility.
  return `${Math.max(6, Math.round(px * this.scaleUnit))}px`;
}

/** A baseline-authored length — padding, row pitch, offset — in canvas units. */
private u(px: number): number {
  return Math.round(px * this.scaleUnit);
}

