/**
 * The one way in for a repaint. Everything here repaints from scratch —
 * every game object destroyed and rebuilt — which is fine at rest and
 * fatal mid-drag: the token under the pointer would be destroyed and
 * rebuilt back at its old slot, out of the player's hand. So a drag holds
 * paints back, and `RepaintGate` replays the one that was owed the moment
 * the drop lands (see `beginTokenDrag`).
 */
private paint(): void {
  if (!this.repaintGate.requestPaint()) return;
  this.paintNow();
}

/**
 * A genuine size change. The paint that follows one is from scratch at the
 * new size, so any drag in flight and any repaint it was owed are dropped
 * — a `dragend` arriving afterwards has nothing left to replay. Walkers go
 * too: their pixel positions belong to a floor plan that no longer exists,
 * so staff re-park on the new one.
 *
 * `repaint` is false when the caller is about to tear this scene down and
 * boot a fresh one at the new size (see `mountRestaurantArenaScene`).
 */
resized(repaint = true): void {
  this.repaintGate.resize();
  this.walkers.clear();
  this.dropHints = undefined;
  if (repaint && this.sys.isActive()) this.paintNow();
}

/** Walk the staff toward wherever the state has assigned them. */
update(_time: number, delta: number): void {
  if (this.walkers.size === 0) return;
  const sim = this.state.sim;
  // A stopped clock stops the floor: nobody crosses the room while the
  // shift is paused for a decision.
  const speed = sim?.started && sim.running ? Math.max(0, sim.speed || 1) : 0;
  for (const [role, walker] of this.walkers) {
    const wasWalking = walker.walking;
    const moved = walker.step(delta, speed);
    const token = this.staffTokens.get(role);
    if (!token || !token.active) continue;
    if (moved) {
