private drawWorkers(layout: RestaurantArenaLayout): void {
  const compact = layout.compact;
  const offsets = new Map<Location, number>();
  this.staffTokens.clear();
  const live = new Set<Role>();

  for (const worker of this.state.workers) {
    const location = this.visualLocation(worker);
    const offset = offsets.get(location) ?? 0;
    offsets.set(location, offset + 1);
    const slot = this.stackedSlot(location, offset, layout);
    live.add(worker.role);

    // The zone slot is where this worker *belongs*; the walker knows where
    // they actually are. Both a reassignment and a resized floor plan show
    // up here as "your slot moved" — either way they walk to it, down the
    // hallway if it is in another room, across the room if it is not.
    let walker = this.walkers.get(worker.role);
    if (!walker) {
      walker = new StaffWalker(location, slot);
      this.walkers.set(worker.role, walker);
    } else if (!walker.dragging) {
      const displaced = Math.abs(walker.x - slot.x) > 1 || Math.abs(walker.y - slot.y) > 1;
      if (walker.node !== location || displaced) {
        walker.setTarget(location, { ...layout.waypoints, [location]: slot }, layout.spineY);
      }
    }

    const token = this.buildAvatar(walker.x, walker.y, worker.role, worker.load, compact);
    this.staffTokens.set(worker.role, token);
    const figure = token.getByName("figure");
    if (figure instanceof Phaser.GameObjects.Container) figure.setScale(walker.facing, 1);
    const heldHost = worker.role === "host" && Boolean(this.state.seatingHeld) && location === "queue";
    const status = heldHost ? "acting" : (this.workerStatuses.get(worker.role) ?? this.workerStatus(worker));
    this.drawWorkerBadge(token, status, compact, heldHost);
    this.drawSpeechBubble(token, worker.role, compact);
    this.makeTokenDraggable(token, worker.role, walker, layout);
  }

  // A worker who left the roster (a shift restart, a different fixture)
  // should not keep a walker parked on the floor plan.
  for (const role of [...this.walkers.keys()]) {
    if (!live.has(role)) this.walkers.delete(role);
  }
}

// ── Dragging staff between zones ─────────────────────────────────────

/**
 * Reassigning staff is picking someone up and putting them where they are
 * needed — the same gesture as moving a piece on a board, and the reason
 * the floor is drawn as a room rather than a form. The drop dispatches the
 * same `assign_<role>_<zone>` action the keyboard would.
 */
private makeTokenDraggable(
  token: Phaser.GameObjects.Container,
  role: Role,
  walker: StaffWalker,
  layout: RestaurantArenaLayout,
): void {
  // Nothing is draggable behind a modal, or before the doors open: the
  // pre-shift card and the decision card are the only thing to do then.
  if (!this.state.sim?.started || this.state.decision) return;

  const reach = this.u(this.layout.compact ? 13 : 17);
  token.setSize(reach * 2, reach * 2.6);
  token.setInteractive(
    new Phaser.Geom.Rectangle(-reach, -reach * 1.8, reach * 2, reach * 2.6),
    Phaser.Geom.Rectangle.Contains,
  );
  this.input.setDraggable(token);

  // A token sits on top of whatever zone hotspot it is standing on — the
  // host is literally on the door stand — so without this, picking them up
  // would also fire that zone's click.
  token.on("pointerdown", (_pointer: Phaser.Input.Pointer, _x: number, _y: number, event?: Phaser.Types.Input.EventData) => {
    event?.stopPropagation();
  });

  let grabX = 0;
  let grabY = 0;
  token.on("dragstart", (pointer: Phaser.Input.Pointer) => {
    grabX = token.x - pointer.worldX;
    grabY = token.y - pointer.worldY;
    this.repaintGate.beginDrag();
    walker.dragging = true;
    this.tweens.killTweensOf(token);
    token.setDepth(80).setScale(1.12).setAlpha(0.95);
    this.showDropHints(layout, walker.node);
  });

  token.on("drag", (pointer: Phaser.Input.Pointer) => {
    const x = pointer.worldX + grabX;
    const y = pointer.worldY + grabY;
    token.setPosition(x, y);
    walker.x = x;
    walker.y = y;
  });

  token.on("dragend", (pointer: Phaser.Input.Pointer) => {
    walker.dragging = false;
    token.setDepth(20).setScale(1).setAlpha(1);
    this.clearDropHints();
    const dropped = this.zoneAt(pointer.worldX, pointer.worldY, layout);
    if (dropped && dropped !== walker.node) {
      // Leave them standing where they were let go and let the next paint
      // walk them onto their slot in the new zone — the state change that
      // action causes is what makes the move real.
      walker.snap({ x: walker.x, y: walker.y }, dropped);
      this.onAction(`assign_${role}_${dropped}`);
    } else {
      // Dropped nowhere useful: walk back to the slot they came from.
      const home = this.stackedSlot(walker.node, 0, layout);
      walker.setTarget(walker.node, { ...layout.waypoints, [walker.node]: home }, layout.spineY);
    }
    // Whatever landed while the token was in the air gets its one repaint
    // now, with the token back under the scene's control.
    if (this.repaintGate.endDrag()) this.paintNow();
  });
}

/** Which zone a pixel belongs to, for a drop. */
private zoneAt(x: number, y: number, layout: RestaurantArenaLayout): Location | undefined {
  const inside = (rect: ArenaRect) =>
    x >= rect.x && x <= rect.x + rect.width && y >= rect.y && y <= rect.y + rect.height;
  if (inside(layout.doorStand) || inside(layout.door)) return "queue";
  if (inside(layout.pass)) return "pass";
  if (inside(layout.kitchen)) return "kitchen";
  if (inside(layout.dining)) return "floor";
  return undefined;
}

/** Outline the zones a held token can be dropped into, while it is held. */
private showDropHints(layout: RestaurantArenaLayout, from: Location): void {
  this.clearDropHints();
  const hints = this.add.graphics().setDepth(78);
  const zones: [Location, ArenaRect][] = [
    ["kitchen", layout.kitchen],
    ["pass", layout.pass],
    ["floor", layout.dining],
    ["queue", layout.door],
  ];
  const radius = layout.compact ? 3 : 5;
  for (const [location, rect] of zones) {
    if (location === from) continue;
    hints.lineStyle(this.u(2), COLORS.pass, 0.8);
    hints.strokeRoundedRect(rect.x + 1, rect.y + 1, rect.width - 2, rect.height - 2, radius);
  }
  this.dropHints = hints;
}

private clearDropHints(): void {
  this.dropHints?.destroy();
  this.dropHints = undefined;
}

