    this.tweens.killTweensOf(token);
    token.setDepth(80).setScale(1.12).setAlpha(0.95);
    this.showDropHints(layout, walker.node);
  });

  token.on("drag", (pointer: Phaser.Input.Pointer) => {
    const x = pointer.worldX + grabX;
    const y = pointer.worldY + grabY;
    token.setPosition(x, y);
    walker.x = x;
    walker.y = y;
  });

  token.on("dragend", (pointer: Phaser.Input.Pointer) => {
    walker.dragging = false;
    token.setDepth(20).setScale(1).setAlpha(1);
    this.clearDropHints();
    const dropped = this.zoneAt(pointer.worldX, pointer.worldY, layout);
    if (dropped && dropped !== walker.node) {
      // Leave them standing where they were let go and let the next paint
      // walk them onto their slot in the new zone — the state change that
      // action causes is what makes the move real.
      walker.snap({ x: walker.x, y: walker.y }, dropped);
      this.onAction(`assign_${role}_${dropped}`);
    } else {
      // Dropped nowhere useful: walk back to the slot they came from.
      const home = this.stackedSlot(walker.node, 0, layout);
      walker.setTarget(walker.node, { ...layout.waypoints, [walker.node]: home }, layout.spineY);
    }
    // Whatever landed while the token was in the air gets its one repaint
    // now, with the token back under the scene's control.
    if (this.repaintGate.endDrag()) this.paintNow();
  });
}

/** Which zone a pixel belongs to, for a drop. */
private zoneAt(x: number, y: number, layout: RestaurantArenaLayout): Location | undefined {
  const inside = (rect: ArenaRect) =>
    x >= rect.x && x <= rect.x + rect.width && y >= rect.y && y <= rect.y + rect.height;
  if (inside(layout.doorStand) || inside(layout.door)) return "queue";
  if (inside(layout.pass)) return "pass";
  if (inside(layout.kitchen)) return "kitchen";
  if (inside(layout.dining)) return "floor";
  return undefined;
}

/** Outline the zones a held token can be dropped into, while it is held. */
private showDropHints(layout: RestaurantArenaLayout, from: Location): void {
  this.clearDropHints();
  const hints = this.add.graphics().setDepth(78);
  const zones: [Location, ArenaRect][] = [
    ["kitchen", layout.kitchen],
    ["pass", layout.pass],
    ["floor", layout.dining],
    ["queue", layout.door],
  ];
  const radius = layout.compact ? 3 : 5;
  for (const [location, rect] of zones) {
    if (location === from) continue;
    hints.lineStyle(this.u(2), COLORS.pass, 0.8);
    hints.strokeRoundedRect(rect.x + 1, rect.y + 1, rect.width - 2, rect.height - 2, radius);
  }
  this.dropHints = hints;
}

private clearDropHints(): void {
  this.dropHints?.destroy();
  this.dropHints = undefined;
}

